mapper.select:
SELECT
(SELECT name_cn FROM dmp_sku_info ds WHERE ds.sku_no = i.sku_no LIMIT 1 ) productName,
SUM ( i.quantity ) AS salesQuantity,
round( SUM ( ( i.sell_price * i.quantity * i.currency_rate ) ) / 10000, 4 ) sales,
i.sku_no AS name FROM dmp_order_item i
LEFT JOIN dmp_order_info o ON i.order_id = o.ID



            o.paid_time >= #{params.startTime}


            AND o.paid_time <= #{params.endTime}


    /*发货时间*/


            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time <= #{params.endTime}


    /*部门*/

        AND o.dept_id IN

            #{deptId}


    /*平台*/

        AND o.source_platform IN

            #{platform}


    /*站点*/

        AND o.site IN

            #{site}



    /*店铺*/

        AND o.shop_no IN

            #{shopNo}



    /*sku*/

        AND i.platform_sku IN

            #{sku}


    /*品类*/

        AND i.category_id IN

            #{category}


    /*品牌*/

        AND i.brand_id IN

            #{brand}



    /*用户id*/

        AND o.charge_id IN

            #{userId}


    /*权限*/

        #{params.param}

    GROUP BY sku_no
    ORDER BY sales ASC

SELECT round( SUM ( i.sell_price * i.quantity * i.currency_rate ), 2 ) sales,
i.sku_no,COUNT ( i.order_id ) orderCount,SUM ( i.quantity ) AS salesQuantity,
o.paid_time  AS flagDate
FROM dmp_order_item i LEFT JOIN dmp_order_info o ON i.order_id = o.id



            o.paid_time >= #{params.startTime}


            AND o.paid_time <= #{params.endTime}


    /*发货时间*/


            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time <= #{params.endTime}


    /*部门*/

        AND o.dept_id IN

            #{deptId}


    /*平台*/

        AND o.source_platform IN

            #{platform}


    /*站点*/

        AND o.site IN

            #{site}



    /*店铺*/

        AND o.shop_no IN

            #{shopNo}



    /*sku*/

        AND i.platform_sku IN

            #{sku}


    /*品类*/

        AND i.category_id IN

            #{category}


    /*品牌*/

        AND i.brand_id IN

            #{brand}



    /*用户id*/

        AND o.charge_id IN

            #{userId}


    /*权限*/

        #{params.param}


GROUP BY i.sku_no,
o.paid_time
